<script>
    // Elements
    const tooltip = document.getElementById('tooltip');
    const canvas = document.getElementById('canvasArea');
    const defaultView = document.getElementById('defaultView');
    const detailView = document.getElementById('detailView');

    // Tooltip Logic
    document.querySelectorAll('.stream-line').forEach(line => {
        line.addEventListener('mouseenter', (e) => {
            // Highlight logic
            e.target.classList.add('active');

            // Data
            const data = JSON.parse(e.target.getAttribute('data-stream'));
            if(!data) return;

            // Render HTML
            tooltip.innerHTML = `
                <div class="tt-header">${data.id} · ${data.name}</div>
                <div class="tt-row"><span>T</span><span class="tt-val">${data.T}</span></div>
                <div class="tt-row"><span>P</span><span class="tt-val">${data.P}</span></div>
                <div class="tt-row"><span>Flow</span><span class="tt-val">${data.Flow}</span></div>
                <div class="tt-comp">${data.comp}</div>
            `;

            // Position
            tooltip.style.left = (e.pageX + 15) + 'px';
            tooltip.style.top = (e.pageY + 15) + 'px';
            tooltip.classList.add('visible');
        });

        line.addEventListener('mousemove', (e) => {
            tooltip.style.left = (e.pageX + 15) + 'px';
            tooltip.style.top = (e.pageY + 15) + 'px';
        });

        line.addEventListener('mouseleave', (e) => {
            e.target.classList.remove('active');
            tooltip.classList.remove('visible');
        });
    });

    // Panel Switching Logic
    function showDetail(unitId) {
        if(unitId === 'R-102') {
            defaultView.classList.add('hidden');
            detailView.classList.add('active');

            // Optional: Highlight unit in SVG
            document.getElementById('unit-R102').querySelector('rect').setAttribute('stroke', '#000');
            document.getElementById('unit-R102').querySelector('rect').setAttribute('stroke-width', '3');
        }
    }

    function hideDetail() {
        detailView.classList.remove('active');
        defaultView.classList.remove('hidden');

        // Reset highlight
         document.getElementById('unit-R102').querySelector('rect').setAttribute('stroke', '#333');
         document.getElementById('unit-R102').querySelector('rect').setAttribute('stroke-width', '1.5');
    }

    // Simple Pan Simulation (Visual only)
    let isDown = false;
    let startX, startY, scrollLeft, scrollTop;

    canvas.addEventListener('mousedown', (e) => {
        isDown = true;
        startX = e.pageX - canvas.offsetLeft;
        startY = e.pageY - canvas.offsetTop;
    });

    canvas.addEventListener('mouseup', () => isDown = false);
    canvas.addEventListener('mouseleave', () => isDown = false);

    canvas.addEventListener('mousemove', (e) => {
        if (!isDown) return;
        e.preventDefault();
        // Just visual feedback for "dragging"
        canvas.style.cursor = 'grabbing';
    });

    canvas.addEventListener('mouseup', () => {
        canvas.style.cursor = 'grab';
    });

</script>

</body>
</html>
